// 本账纯读截面组件，不把人工租约壳冒完整资产/司法已验；World必须先验完整Shop。
#include "resident/domains/commerce/private_shop_asset_responsibilities.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool ok,const char* msg){++checks;if(!ok)throw std::runtime_error(msg);}StableId header(CommonStore& c,const StableId& prefix,const StableId& kind,const StableId& domain="private_shops"){auto id=c.next_id(prefix);check(id.ok,"allocate real source ID");check(c.append_fact({id.value,kind,domain}).ok,"append real source head");return id.value;}}
int main(){try{auto catalog=std::make_shared<CommonCatalog>();CommonStore c{CommonState{},catalog};ActorRecord actor;actor.id="owner";actor.wallet_id="wallet";actor.inventory_id="bag";c.state().actors.insert(actor.id,actor);c.state().wallets.insert("wallet",{"wallet",{Owner::Kind::actor,"owner",{}},100,{}});c.state().inventories.insert("bag",{"bag",{Owner::Kind::actor,"owner",{}},100,0,{}});PrivateShopState s;PrivateShopPrivateAssetScope scope{"owner",{"wallet"},{"bag"}};check(read_private_shop_private_asset_responsibilities(c,nullptr,scope).ok,"old absent profile remains available");PrivateShopRecord shop;shop.id=header(c,"private_shop","private_shop_opened");shop.terms.proprietor_actor_id="owner";shop.terms.payer_wallet_id="wallet";s.shops.insert(shop.id,shop);check(!read_private_shop_private_asset_responsibilities(c,nullptr,scope).ok,"real shop head requires explicit same-state pointer");auto current=read_private_shop_private_asset_responsibilities(c,&s,scope);check(current.ok&&current.value.blockers.size()==1,"active original proprietor lease blocks private assets");auto before=header(c,"family_inheritance","family_inheritance_settled","family_inheritance");PrivateShopClosingRecord closed;closed.id=header(c,"private_shop_closed","private_shop_closed");closed.shop_id=shop.id;s.closings.insert(closed.id,closed);s.shops.find(shop.id)->status="closed";current=read_private_shop_private_asset_responsibilities(c,&s,scope);check(current.ok&&current.value.blockers.empty(),"actual prior closure ends present lease liability");auto past=read_private_shop_private_asset_responsibilities_before_inheritance(c,&s,scope,before,0);check(past.ok&&past.value.blockers.size()==1,"later closing cannot clear earlier inheritance");auto after=header(c,"family_inheritance","family_inheritance_settled","family_inheritance");past=read_private_shop_private_asset_responsibilities_before_inheritance(c,&s,scope,after,0);check(past.ok&&past.value.blockers.empty(),"same-tick actual prior close clears that later boundary");PrivateShopRecord later=shop;later.id=header(c,"private_shop","private_shop_opened");s.shops.insert(later.id,later);past=read_private_shop_private_asset_responsibilities_before_inheritance(c,&s,scope,after,0);check(past.ok&&past.value.blockers.empty(),"later opening cannot invalidate earlier lawful clearance");current=read_private_shop_private_asset_responsibilities(c,&s,scope);check(current.ok&&current.value.blockers.size()==1&&current.value.blockers.front().source_id==later.id,"current new lease is still pending");check(!read_private_shop_private_asset_responsibilities_before_inheritance(c,&s,scope,closed.id,0).ok,"arbitrary closing head cannot become inheritance boundary");const auto raw=encode_common_state(c.state());past=read_private_shop_private_asset_responsibilities_before_inheritance(c,&s,scope,after,0);check(past.ok&&compare_boundary(raw,encode_common_state(c.state())).exact(),"history query never changes cash IDs or facts");c.state().facts.find(closed.id)->kind="private_shop_opened";check(!read_private_shop_private_asset_responsibilities(c,&s,scope).ok,"wrong closing header cannot clear liability");std::cout<<checks<<"/0 private shop responsibility source checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
